/*
  asariko cover page: the particle intro shown over the home page on every load.
  The overlay markup, its styles and the ENTER handling live in index.html (so ENTER still works if this
  file fails to load). This file only draws: photo background, particle wordmark/logo, morph and shake.
  Settings were chosen in DEMO/cover-particles-debug.html.
*/
(function () {
  var cover = document.getElementById('cover');
  if (!cover || cover.hidden) return;                // no cover (or reduced motion): nothing to draw

  // wordmark + logo shapes, embedded so the particles can read their pixels even when the page is opened as a file
  const SRC = ["data:image/png;base64,", "data:image/png;base64,"];

  // ---- Ayarlar (settings) ----
  const SPRING = 0.035;    // eve dönüş kuvveti
  const DAMP = 0.86;       // sürtünme
  const GLYPHS = ".:-=+*#%01░▒";
  const INK = [255, 255, 255];   // harf rengi: beyaz
  const CATEGORY = 'blurred';    // static.photos kategorisi
  const SIZE = '1200x630';       // foto çözünürlüğü
  const FIRST_PHOTO = 124;       // ilk açılışta gösterilen foto
  const LIGHT_MAX = 170;         // beyaz harf için: ortası bundan parlak fotolar atlanır (0 siyah – 255 beyaz)
  const MAX_TRIES = 6;           // üst üste en fazla kaç foto atlanabilir
  // yüzü net görünen fotolar: bu numaralar hiç gösterilmez (yenisini eklemek için listeye yaz)
  const SKIP = {
    blurred: [154, 206, 75, 97, 188, 170, 81, 125, 249, 19],
    vintage: [32, 59, 62, 4, 152, 169, 245, 44, 168, 98, 0, 135, 164, 159, 121, 185], // vintage seçilirse diye hazır
  };
  const ENTER_PUSH = 0.25;       // ENTER itme efekti — 1 = logo ile aynı, küçük sayı = daha az dağılır
  const SHAKE_SPEED = 20;        // salla-dönüştür: bir hareketin "hızlı" sayılması için gereken px
  const SHAKE_TURNS = 4;         // kaç yön değişimi gerekli

  const bg = document.getElementById('coverBg');
  const cv = document.getElementById('coverCanvas');
  const enterBtn = cover.querySelector('.enter');
  const ctx = cv.getContext('2d');
  let coverGone = false;
  window.addEventListener('asariko:enter', function () { coverGone = true; });

  // ---- photo background: next photo is preloaded and brightness-checked while the current one shows ----
  const photoUrl = seed => 'https://static.photos/' + CATEGORY + '/' + SIZE + '/' + seed;
  const randomSeed = () => { let n; do n = Math.floor(Math.random() * 256); while ((SKIP[CATEGORY] || []).includes(n)); return n; };
  const thumb = document.createElement('canvas'); thumb.width = 32; thumb.height = 18;
  const tx2 = thumb.getContext('2d', { willReadFrequently: true });
  function brightness(img) {                          // fotoyu 32×18'e küçült, ortasını ölç
    tx2.drawImage(img, 0, 0, 32, 18);
    const d = tx2.getImageData(6, 4, 20, 10).data;
    let sum = 0;
    for (let i = 0; i < d.length; i += 4) sum += 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
    return Math.round(sum / (d.length / 4));
  }
  function loadGood(seed, tries) {
    seed = seed == null ? randomSeed() : seed; tries = tries || 0;
    return new Promise(resolve => {
      const img = new Image();
      img.crossOrigin = 'anonymous';                  // piksel okumak için gerekli (static.photos izin veriyor)
      img.alt = '';
      img.onload = () => {
        let ok = true;
        try { ok = brightness(img) <= LIGHT_MAX; } catch (e) { ok = true; }
        resolve(ok || tries + 1 >= MAX_TRIES ? img : loadGood(null, tries + 1));
      };
      img.onerror = () => resolve(tries + 1 >= MAX_TRIES ? null : loadGood(null, tries + 1));
      img.src = photoUrl(seed);
    });
  }
  let nextP = loadGood(FIRST_PHOTO), showId = 0;
  function showNext() {
    const my = ++showId, p = nextP;
    nextP = loadGood();                               // bir sonrakini şimdiden indir ve ölç
    p.then(img => { if (img && my === showId) bg.replaceChildren(img); });
  }
  showNext();

  // ---- particles ----
  let W, H, dpr, STEP, RADIUS, shapes = [], parts = [], cur = 0;
  let ESTEP = 2, eparts = [], enterHot = false;
  const mouse = { x: -9999, y: -9999, px: -9999, py: -9999, on: false };
  const imgs = SRC.map(s => { const i = new Image(); i.src = s; return i; });
  Promise.all(imgs.map(i => i.decode())).then(() => { build(); cover.classList.add('particles'); requestAnimationFrame(frame); });
  addEventListener('resize', () => { if (!coverGone) build(); });

  function sample(img, maxW, maxH, step) {           // resmi ekrana sığdır, koyu pikselleri hedef noktalara çevir
    const s = Math.min(maxW / img.width, maxH / img.height);
    const w = Math.max(1, Math.round(img.width * s)), h = Math.max(1, Math.round(img.height * s));
    const ox = (W - w) / 2, oy = (H - h) / 2;
    const off = document.createElement('canvas');
    off.width = w; off.height = h;
    const o = off.getContext('2d');
    o.drawImage(img, 0, 0, w, h);
    const d = o.getImageData(0, 0, w, h).data;
    const pts = [];
    for (let y = 0; y < h; y += step)
      for (let x = 0; x < w; x += step) {
        const i = (y * w + x) * 4;
        if (d[i + 3] > 128 && d[i] < 128 && Math.random() < 0.9) pts.push([ox + x, oy + y]);
      }
    return { pts, w };
  }

  function build() {
    if (!imgs.every(i => i.naturalWidth)) return;
    dpr = Math.min(devicePixelRatio || 1, 2);
    W = innerWidth; H = innerHeight;
    if (!W || !H) return;
    cv.width = W * dpr; cv.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const tw = Math.min(W * 0.9 / imgs[0].width, H * 0.6 / imgs[0].height) * imgs[0].width;
    STEP = Math.max(3, Math.min(8, Math.round(tw / 240)));
    RADIUS = Math.max(40, tw * 0.09);
    shapes = [sample(imgs[0], W * 0.9, H * 0.6, STEP).pts, sample(imgs[1], W * 0.7, H * 0.6, STEP).pts];

    // ENTER, drawn with the same glyph particles, positioned over the real button
    const r = enterBtn.getBoundingClientRect();
    const tc = document.createElement('canvas'), tx = tc.getContext('2d');
    const F = '700 100px ui-monospace, Menlo, monospace', LABEL = 'ENTER';
    const setup = () => { tx.font = F; tx.letterSpacing = '20px'; tx.textBaseline = 'middle'; };
    setup(); tc.width = Math.ceil(tx.measureText(LABEL).width); tc.height = 120;
    setup(); tx.fillText(LABEL, 0, 60);
    const ex = r.left + r.width / 2 - W / 2, ey = r.top + r.height / 2 - H / 2;
    eparts = sample(tc, r.width, r.height, ESTEP).pts.map(([x, y]) => ({
      x: Math.random() * W, y: Math.random() * H, vx: 0, vy: 0, hx: x + ex, hy: y + ey, on: true, vis: 0,
      g: GLYPHS[(Math.random() * GLYPHS.length) | 0], a: 0.35 + Math.random() * 0.65,
    }));
    const n = Math.max(shapes[0].length, shapes[1].length);
    parts = [];
    for (let i = 0; i < n; i++) parts.push({
      x: Math.random() * W, y: Math.random() * H, vx: 0, vy: 0, hx: 0, hy: 0, on: true, vis: 0,
      g: GLYPHS[(Math.random() * GLYPHS.length) | 0], a: 0.35 + Math.random() * 0.65,
    });
    assign();
  }

  function assign() {                                 // parçacıkları aktif şeklin noktalarına karışık dağıt; fazlası söner
    const pts = shapes[cur];
    for (let i = parts.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; [parts[i], parts[j]] = [parts[j], parts[i]]; }
    parts.forEach((p, i) => { p.on = i < pts.length; const t = pts[i % pts.length]; p.hx = t[0]; p.hy = t[1]; });
  }

  function morph() {                                  // wordmark ⇄ logo, with a new photo each time
    cur = 1 - cur;
    showNext();
    assign();
    for (const p of parts) { const a = Math.random() * Math.PI * 2, f = 4 + Math.random() * 10; p.vx += Math.cos(a) * f; p.vy += Math.sin(a) * f; }
  }

  // salla-dönüştür: fareyi hızlıca 4 kez sağa-sola sallamak da morph'u tetikler (iki yöne de)
  let shakeDir = 0, shakeTurns = [], shakeCooldown = 0;
  function shake(e) {
    if (e.pointerType !== 'mouse' || mouse.x < -9000) return;
    const dx = e.clientX - mouse.x, now = performance.now();
    if (Math.abs(dx) < SHAKE_SPEED || now < shakeCooldown) return;
    const dir = Math.sign(dx);
    if (shakeDir && dir !== shakeDir) shakeTurns.push(now);
    shakeDir = dir;
    shakeTurns = shakeTurns.filter(t => now - t < 1000);
    if (shakeTurns.length >= SHAKE_TURNS) { morph(); shakeTurns = []; shakeDir = 0; shakeCooldown = now + 1500; }
  }
  function move(e) { shake(e); mouse.x = e.clientX; mouse.y = e.clientY; mouse.on = true; }
  const off = () => { mouse.on = false; mouse.x = mouse.y = mouse.px = mouse.py = -9999; };
  cover.addEventListener('pointermove', move);
  cover.addEventListener('pointerdown', move);
  cover.addEventListener('pointerleave', off);
  cover.addEventListener('pointerup', e => { if (e.pointerType !== 'mouse') off(); });
  cover.addEventListener('pointercancel', off);
  cv.addEventListener('click', morph);
  enterBtn.addEventListener('pointerenter', () => { enterHot = true; });
  enterBtn.addEventListener('pointerleave', () => { enterHot = false; });

  function hex(x, y, r) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) { const t = Math.PI / 6 + i * Math.PI / 3; ctx.lineTo(x + r * Math.cos(t), y + r * Math.sin(t)); }
    ctx.closePath();
  }

  function frame() {
    if (coverGone) return;
    ctx.clearRect(0, 0, W, H);
    const mvx = mouse.px > -9000 ? mouse.x - mouse.px : 0;
    const mvy = mouse.py > -9000 ? mouse.y - mouse.py : 0;
    mouse.px = mouse.x; mouse.py = mouse.y;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    for (const [list, fs, rad] of [[parts, STEP + 1, RADIUS], [eparts, ESTEP + 2, RADIUS * ENTER_PUSH]]) {
      const R2 = rad * rad, kick = rad / 18;
      ctx.font = fs + 'px ui-monospace, Menlo, monospace';
      for (const p of list) {
        const dx = p.x - mouse.x, dy = p.y - mouse.y, d2 = dx * dx + dy * dy;
        if (d2 < R2) {
          const dist = Math.sqrt(d2) || 1, push = (rad - dist) / rad;
          p.vx += (dx / dist) * push * kick + mvx * push * 0.25;
          p.vy += (dy / dist) * push * kick + mvy * push * 0.25;
        }
        p.vx = (p.vx + (p.hx - p.x) * SPRING) * DAMP;
        p.vy = (p.vy + (p.hy - p.y) * SPRING) * DAMP;
        p.x += p.vx; p.y += p.vy;
        p.vis += ((p.on ? 1 : 0) - p.vis) * 0.06;
        if (p.vis < 0.02) continue;
        if (Math.random() < 0.002) p.g = GLYPHS[(Math.random() * GLYPHS.length) | 0];
        const speed = Math.min(1, Math.abs(p.vx) + Math.abs(p.vy));
        const hot = list === eparts && enterHot ? 0.35 : 0;
        ctx.fillStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + Math.min(1, p.a + hot + speed * 0.5) * p.vis + ')';
        ctx.fillText(p.g, p.x, p.y);
      }
    }
    if (mouse.on) {                                   // turuncu altıgen imleç
      ctx.shadowColor = 'rgba(255,68,0,0.8)'; ctx.shadowBlur = 10;
      ctx.strokeStyle = '#ff4400'; ctx.lineWidth = 2;
      hex(mouse.x, mouse.y, Math.max(8, RADIUS * 0.12)); ctx.stroke();
      ctx.shadowBlur = 0;
    }
    requestAnimationFrame(frame);
  }
})();
